          import {LEGACY_FACTUAL_OVERLAY_MODULES,PUBLIC_RUNTIME_MODULES} from './docs/engineer-osint/runtime-modules.mjs';
          const file='data-integrity-identity-fixes.js',id='engineer-data-integrity-identity-fixes-module';
          const legacy=LEGACY_FACTUAL_OVERLAY_MODULES.map(([,f])=>f);
          const publicActive=PUBLIC_RUNTIME_MODULES.some(([runtimeId,f])=>runtimeId===id&&f===file);
          if(legacy.length===1&&legacy[0]===file&&publicActive)console.log('phase=PRE_RETIREMENT');
