        run: |
          git diff --exit-code -- docs/engineer-osint/data
          node - <<'NODE'
          const fs=require('fs');
          const p='docs/engineer-osint-dist/identity-fix-retirement-readiness-audit.json';
          const a=JSON.parse(fs.readFileSync(p,'utf8'));
          if(a.status!=='PASS'||a.identity_overlay_residual_mutations!==0||a.other_public_runtime_sentinel_consumer_count!==0)throw new Error('identity retirement pre-browser evidence mismatch');
          if(a.active_legacy_factual_module_count!==1||a.identity_fix_runtime_active!==true||a.built_identity_script_count!==1||a.simulated_no_identity_script_count!==0)throw new Error('identity retirement runtime scope mismatch');
          if(a.browser_normalized_dom_parity!==null||a.browser_parity_evidence_pending!==true||a.ready_for_separate_retirement_authorization_review!==false)throw new Error('browser readiness state broadened before browser proof');
          for(const key of ['canonical_write_performed','run_store_manifest_edit_performed','identity_fix_runtime_removal_authorized','identity_overlay_retirement_authorized','runtime_manifest_edit_authorized','identity_fix_file_deletion_authorized','legacy_baseline_edit_authorized'])if(a[key]!==false)throw new Error(`identity retirement safety boundary broadened: ${key}`);
          NODE

      - name: Headless browser active vs simulated retired parity
        if: steps.retirement.outputs.phase == 'PRE_RETIREMENT'
        shell: bash
        run: |
          set -euo pipefail
          browser="$(command -v google-chrome || command -v google-chrome-stable || command -v chromium || command -v chromium-browser || true)"
          test -n "$browser"
          active="${GITHUB_WORKSPACE}/docs/engineer-osint-dist/v4544-identity-active.html"
          retired="${GITHUB_WORKSPACE}/docs/engineer-osint-dist/v4544-identity-retired-simulated.html"
          for pair in "active:$active" "retired:$retired"; do
            key="${pair%%:*}"; path="${pair#*:}"
            "$browser" --headless=new --no-sandbox --disable-gpu --disable-dev-shm-usage --allow-file-access-from-files --virtual-time-budget=5000 --dump-dom "file://${path}" > "/tmp/v4544-${key}-dom.html"
            test -s "/tmp/v4544-${key}-dom.html"
            grep -qi '<html' "/tmp/v4544-${key}-dom.html"
            grep -q 'ENGINEER OSINT' "/tmp/v4544-${key}-dom.html"
          done
          grep -q 'engineer-data-integrity-identity-fixes-module' /tmp/v4544-active-dom.html
          ! grep -q 'engineer-data-integrity-identity-fixes-module' /tmp/v4544-retired-dom.html
          python - <<'PY'
          from pathlib import Path
          import re, hashlib, html
          bilingual=re.compile(
              r'(?P<open><(?P<tag>[A-Za-z][A-Za-z0-9:-]*)\b(?=[^>]*\bdata-label-cs="(?P<cs>[^"]*)")(?=[^>]*\bdata-label-en="(?P<en>[^"]*)")[^>]*>)'
              r'(?P<text>[^<>]*)(?P<close></(?P=tag)>)',re.I)
          def canon(m):
              text=html.unescape(m.group('text')).strip(); cs=html.unescape(m.group('cs')).strip(); en=html.unescape(m.group('en')).strip()
              return m.group('open')+m.group('cs')+m.group('close') if text in {cs,en} else m.group(0)
          def norm(path):
              s=Path(path).read_text(errors='replace')
              s=re.sub(r'<script\b[^>]*>[\s\S]*?</script>','',s,flags=re.I)
              s=bilingual.sub(canon,s)
              return re.sub(r'\s+',' ',s).strip()
          a=norm('/tmp/v4544-active-dom.html'); b=norm('/tmp/v4544-retired-dom.html')
          if a!=b: raise SystemExit('HEADLESS_IDENTITY_RETIREMENT_PARITY: normalized DOM differs')
          digest=hashlib.sha256(a.encode()).hexdigest()
          Path('/tmp/v4544-browser-parity.txt').write_text(f'PASS sha256={digest}\n')
          print(f'HEADLESS_IDENTITY_RETIREMENT_PARITY=PASS sha256={digest}')
          PY

      - name: Mark readiness evidence browser-complete without authorizing retirement
        if: steps.retirement.outputs.phase == 'PRE_RETIREMENT'
        run: |
          node - <<'NODE'
          const fs=require('fs');
          const p='docs/engineer-osint-dist/identity-fix-retirement-readiness-audit.json';
          const a=JSON.parse(fs.readFileSync(p,'utf8'));
          a.browser_normalized_dom_parity=true;
          a.browser_parity_evidence_pending=false;
          a.ready_for_separate_retirement_authorization_review=true;
          if(a.identity_fix_runtime_removal_authorized!==false||a.identity_overlay_retirement_authorized!==false||a.runtime_manifest_edit_authorized!==false||a.identity_fix_file_deletion_authorized!==false||a.legacy_baseline_edit_authorized!==false)throw new Error('browser completion broadened retirement authorization');
          fs.writeFileSync(p,JSON.stringify(a,null,2)+'\n');
          fs.appendFileSync('docs/engineer-osint-dist/health.txt','identity_fix_retirement_browser_parity=pass\nidentity_fix_retirement_ready_for_separate_authorization_review=1\nidentity_fix_retirement_authorized=0\n');
          console.log('IDENTITY_FIX_RETIREMENT_READINESS=PASS_NO_AUTHORIZATION');
