      - name: Audit authorized post-retirement state
        if: steps.retirement.outputs.phase == 'POST_RETIREMENT'
        run: |
          node docs/engineer-osint/audit-identity-fix-retirement.mjs
          git diff --exit-code -- docs/engineer-osint/data
