          const fs=require('fs');
          const p='docs/engineer-osint-dist/identity-fix-retirement-audit.json';
          const a=JSON.parse(fs.readFileSync(p,'utf8'));
          if(a.status!=='PASS'||a.identity_fix_runtime_active!==false||a.identity_fix_runtime_retired!==true||a.identity_fix_source_retained!==true)throw new Error('post-retirement identity state mismatch');
          if(a.active_legacy_factual_module_count!==0||a.active_legacy_baseline_module_count!==0||a.historical_identity_source_residual_mutations!==0||a.other_public_runtime_sentinel_consumer_count!==0)throw new Error('post-retirement zero-debt proof failed');
          if(a.built_identity_script_count!==0||a.transition_guard_runtime_active!==true||a.transition_guard_script_count!==1)throw new Error('post-retirement runtime contract failed');
          if(a.canonical_write_performed!==false||a.run_store_manifest_edit_performed!==false||a.run_appended!==false||a.source_file_deleted!==false||a.other_runtime_module_removed!==false)throw new Error('post-retirement safety boundary broadened');
